function [CC, CV] = control_cccv(Vmed)

persistent estadoCV

% Inicialización
if isempty(estadoCV)
    estadoCV = false;
end

% Si todavía estamos en CC y se alcanza 4.2 V,
% cambiar permanentemente a CV
if ~estadoCV && Vmed >= 4.2
    estadoCV = true;
end

% Salidas hacia los conmutadores
if estadoCV
    CC = 0;
    CV = 1;
else
    CC = 1;
    CV = 0;
end

end
